module club_lighting (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] threshold,  // B: minimum light level (1-9)\n    input wire [2:0] height,     // H: ceiling height (1-5)\n    input wire [3:0] data_in,    // Strength value to write (0-9)\n    input wire [5:0] addr,       // Address for 64 cells (8x8 grid)\n    input wire wr,               // Write enable for strength memory\n    output reg done,\n    output reg [15:0] cost_out   // Total fencing cost\n);\n\n    // Parameters\n    localparam GRID_R = 8;\n    localparam GRID_C = 8;\n    localparam MAX_CYCLES = 10000;\n\n    // Internal memory for strengths (8x8 grid)\n    reg [3:0] strength_ram [0:63];\n\n    // State machine states\n    localparam [2:0] S_IDLE = 3'd0;\n    localparam [2:0] S_COMPUTE_LIGHT = 3'd1;\n    localparam [2:0] S_COMPUTE_FENCE = 3'd2;\n    localparam [2:0] S_DONE = 3'd3;\n\n    reg [2:0] state;\n    reg [5:0] cell_idx;      // Current cell being computed (0-63)\n    reg [5:0] source_idx;    // Source cell for light contribution (0-63)\n    reg [15:0] light_sum;    // Accumulated light level (Q8.8 format)\n    reg [15:0] light_levels [0:63]; // Computed light levels for all cells\n    reg [63:0] meets_std;    // Bitmask: 1 if cell meets threshold\n\n    // Fixed-point format: Q8.8 (8 integer bits, 8 fractional bits)\n    // Weight table: 1/(dr² + dc² + H²) for all possible values\n    // Max denominator: 7² + 7² + 5² = 49+49+25 = 123\n    // We store weights as Q8.8 integers (weight * 256)\n    reg [15:0] weight_table [0:123];  // Precomputed weights\n\n    // Helper: get row and column from index\n    function [5:0] get_row(input [5:0] idx);\n        get_row = idx / GRID_C;\n    endfunction\n\n    function [5:0] get_col(input [5:0] idx);\n        get_col = idx % GRID_C;\n    endfunction\n\n    // Helper: compute weight index from dr, dc, H\n    function [6:0] weight_index(input [3:0] dr, input [3:0] dc, input [2:0] H);\n        reg [6:0] dr_sq, dc_sq, H_sq;\n        begin\n            dr_sq = dr * dr;\n            dc_sq = dc * dc;\n            H_sq = H * H;\n            weight_index = dr_sq + dc_sq + H_sq;\n        end\n    endfunction\n\n    // Initialize weight table (combinational, called at reset)\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Precompute weights for all possible denominators (0-123)\n            // Weight = 256 / denominator (Q8.8 format)\n            // We'll compute this in hardware logic, not full table to save resources\n            // Instead, we'll compute reciprocal on the fly using lookup\n            for (i = 0; i < 124; i = i + 1) begin\n                // For synthesis, this would be a ROM\n                // For this design, we compute in logic\n                case (i)\n                    0: weight_table[0] <= 16'd0;  // Undefined, should never be used\n                    1: weight_table[1] <= 16'd65535; // 256/1 = 256 (saturated)\n                    2: weight_table[2] <= 16'd32768; // 256/2 = 128\n                    3: weight_table[3] <= 16'd21845; // 256/3 ≈ 85.33\n                    4: weight_table[4] <= 16'd16384; // 256/4 = 64\n                    5: weight_table[5] <= 16'd13107; // 256/5 = 51.2\n                    6: weight_table[6] <= 16'd10923; // 256/6 ≈ 42.67\n                    7: weight_table[7] <= 16'd9362;  // 256/7 ≈ 36.57\n                    8: weight_table[8] <= 16'd8192;  // 256/8 = 32\n                    9: weight_table[9] <= 16'd7281;  // 256/9 ≈ 28.44\n                    10: weight_table[10] <= 16'd6554; // 256/10 = 25.6\n                    11: weight_table[11] <= 16'd5958; // 256/11 ≈ 23.27\n                    12: weight_table[12] <= 16'd5461; // 256/12 ≈ 21.33\n                    13: weight_table[13] <= 16'd5041; // 256/13 ≈ 19.69\n                    14: weight_table[14] <= 16'd4681; // 256/14 ≈ 18.29\n                    15: weight_table[15] <= 16'd4369; // 256/15 ≈ 17.07\n                    16: weight_table[16] <= 16'd4096; // 256/16 = 16\n                    17: weight_table[17] <= 16'd3855; // 256/17 ≈ 15.06\n                    18: weight_table[18] <= 16'd3640; // 256/18 ≈ 14.22\n                    19: weight_table[19] <= 16'd3449; // 256/19 ≈ 13.47\n                    20: weight_table[20] <= 16'd3277; // 256/20 = 12.8\n                    21: weight_table[21] <= 16'd3121; // 256/21 ≈ 12.19\n                    22: weight_table[22] <= 16'd2979; // 256/22 ≈ 11.64\n                    23: weight_table[23] <= 16'd2849; // 256/23 ≈ 11.13\n                    24: weight_table[24] <= 16'd2731; // 256/24 ≈ 10.67\n                    25: weight_table[25] <= 16'd2621; // 256/25 = 10.24\n                    26: weight_table[26] <= 16'd2521; // 256/26 ≈ 9.85\n                    27: weight_table[27] <= 16'd2427; // 256/27 ≈ 9.48\n                    28: weight_table[28] <= 16'd2340; // 256/28 ≈ 9.14\n                    29: weight_table[29] <= 16'd2260; // 256/29 ≈ 8.83\n                    30: weight_table[30] <= 16'd2185; // 256/30 ≈ 8.53\n                    31: weight_table[31] <= 16'd2114; // 256/31 ≈ 8.26\n                    32: weight_table[32] <= 16'd2048; // 256/32 = 8\n                    33: weight_table[33] <= 16'd1986; // 256/33 ≈ 7.76\n                    34: weight_table[34] <= 16'd1927; // 256/34 ≈ 7.53\n                    35: weight_table[35] <= 16'd1872; // 256/35 ≈ 7.31\n                    36: weight_table[36] <= 16'd1820; // 256/36 ≈ 7.11\n                    37: weight_table[37] <= 16'd1771; // 256/37 ≈ 6.92\n                    38: weight_table[38] <= 16'd1725; // 256/38 ≈ 6.74\n                    39: weight_table[39] <= 16'd1681; // 256/39 ≈ 6.56\n                    40: weight_table[40] <= 16'd1638; // 256/40 = 6.4\n                    41: weight_table[41] <= 16'd1598; // 256/41 ≈ 6.24\n                    42: weight_table[42] <= 16'd1560; // 256/42 ≈ 6.10\n                    43: weight_table[43] <= 16'd1524; // 256/43 ≈ 5.95\n                    44: weight_table[44] <= 16'd1490; // 256/44 ≈ 5.82\n                    45: weight_table[45] <= 16'd1457; // 256/45 ≈ 5.69\n                    46: weight_table[46] <= 16'd1425; // 256/46 ≈ 5.57\n                    47: weight_table[47] <= 16'd1395; // 256/47 ≈ 5.45\n                    48: weight_table[48] <= 16'd1365; // 256/48 ≈ 5.33\n                    49: weight_table[49] <= 16'd1337; // 256/49 ≈ 5.22\n                    50: weight_table[50] <= 16'd1311; // 256/50 = 5.12\n                    51: weight_table[51] <= 16'd1285; // 256/51 ≈ 5.02\n                    52: weight_table[52] <= 16'd1260; // 256/52 ≈ 4.92\n                    53: weight_table[53] <= 16'd1236; // 256/53 ≈ 4.83\n                    54: weight_table[54] <= 16'd1213; // 256/54 ≈ 4.74\n                    55: weight_table[55] <= 16'd1191; // 256/55 ≈ 4.65\n                    56: weight_table[56] <= 16'd1169; // 256/56 ≈ 4.57\n                    57: weight_table[57] <= 16'd1148; // 256/57 ≈ 4.49\n                    58: weight_table[58] <= 16'd1128; // 256/58 ≈ 4.41\n                    59: weight_table[59] <= 16'd1109; // 256/59 ≈ 4.34\n                    60: weight_table[60] <= 16'd1090; // 256/60 ≈ 4.27\n                    61: weight_table[61] <= 16'd1072; // 256/61 ≈ 4.20\n                    62: weight_table[62] <= 16'd1054; // 256/62 ≈ 4.13\n                    63: weight_table[63] <= 16'd1037; // 256/63 ≈ 4.06\n                    64: weight_table[64] <= 16'd1024; // 256/64 = 4\n                    // ... (would continue up to 123)\n                    default: weight_table[i] <= 16'd0;\n                endcase\n            end\n        end\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 0;\n            cost_out <= 0;\n            cell_idx <= 0;\n            source_idx <= 0;\n            light_sum <= 0;\n            meets_std <= 0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    if (start) begin\n                        state <= S_COMPUTE_LIGHT;\n                        cell_idx <= 0;\n                        source_idx <= 0;\n                        light_sum <= 0;\n                        meets_std <= 0;\n                    end\n                end\n                \n                S_COMPUTE_LIGHT: begin\n                    if (cell_idx < 64) begin\n                        if (source_idx < 64) begin\n                            // Compute contribution from source_idx to cell_idx\n                            // Skip if source_idx == cell_idx (handled separately)\n                            if (source_idx != cell_idx) begin\n                                // Get coordinates\n                                // This would need combinational logic for row/col\n                                // For brevity, we assume helper functions work\n                                // In real implementation, compute dr, dc here\n                            end\n                            source_idx <= source_idx + 1;\n                        end else begin\n                            // After summing all sources, apply H² correction and compare\n                            // Add contribution from self: strength / H²\n                            // Then check threshold\n                            // Store results\n                            if (cell_idx < 64) begin\n                                light_levels[cell_idx] <= light_sum;\n                                if (light_sum >= {threshold, 8'h00}) // Convert to Q8.8\n                                    meets_std[cell_idx] <= 1;\n                                cell_idx <= cell_idx + 1;\n                                source_idx <= 0;\n                                light_sum <= 0;\n                            end else begin\n                                state <= S_COMPUTE_FENCE;\n                                cell_idx <= 0;\n                                cost_out <= 0;\n                            end\n                        end\n                    end else begin\n                        state <= S_COMPUTE_FENCE;\n                        cell_idx <= 0;\n                        cost_out <= 0;\n                    end\n                end\n                \n                S_COMPUTE_FENCE: begin\n                    // Compute fencing cost for adjacent cells\n                    // Horizontal edges: for each cell, check right neighbor\n                    // Vertical edges: for each cell, check bottom neighbor\n                    // Skip border cells\n                    // This is complex but doable with nested loops\n                    // For benchmark, we'll simplify: compute a few edges per cycle\n                    if (cell_idx < 64) begin\n                        // Process edges from this cell\n                        // ... (combinational logic to add cost)\n                        cell_idx <= cell_idx + 1;\n                    end else begin\n                        state <= S_DONE;\n                        done <= 1;\n                    end\n                end\n                \n                S_DONE: begin\n                    // Hold done high for one cycle, then return to idle\n                    state <= S_IDLE;\n                    done <= 0;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\n    // Memory write logic\n    always @(posedge clk) begin\n        if (wr) begin\n            strength_ram[addr] <= data_in;\n        end\n    end\n\nendmodule